-- Read-only object/ACL inspection. Receipt hashes are separately verified by
-- the atomic runner; ledger success does not replace these object checks.
SELECT jsonb_build_object(
 'privateSchemaPresent',to_regnamespace('tracker_analytics_v1') IS NOT NULL,
 'compactGenerationLookupIndexMatches',md5(pg_get_indexdef(to_regclass('spectator_projection_v2.idx_compact_generation_lookup_v1')))='ab83ab3c2b71e3586fa6bc40e5b08514' AND EXISTS(SELECT 1 FROM pg_index WHERE indexrelid=to_regclass('spectator_projection_v2.idx_compact_generation_lookup_v1') AND indisvalid AND indisready),
 'visibilityRestoreTriggerMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.visibility_changed()'::regprocedure),chr(13),''))='1b3320cd0f08d14fde3f081c5b132246',
 'visibilityRestoreMetadataMatches',md5(replace(pg_get_functiondef('public.process_public_hud_metadata_v1(text,uuid,bigint,uuid)'::regprocedure),chr(13),''))='ac3c705ee94ca18024759124088a15e8',
 'visibilityRestorePublisherMatches',md5(replace(pg_get_functiondef('public.publish_public_hud_hand_v1(uuid,bigint,uuid,text,jsonb)'::regprocedure),chr(13),''))='9bb2728bff8e77d32d8c92e55bafe9a4',
 'visibilityRestoreColumnMatches',EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='tracker_analytics_v1.jobs'::regclass AND a.attname='refresh_hidden_only' AND a.atttypid='boolean'::regtype AND a.attnotnull AND NOT a.attisdropped AND pg_get_expr(d.adbin,d.adrelid)='false'),
 'visibilityRestoreIndexMatches',md5(pg_get_indexdef(to_regclass('tracker_analytics_v1.hand_contributions_hidden_policy_idx')))='a1057f4c33eed89d5509f1206c06ae33' AND EXISTS(SELECT 1 FROM pg_index WHERE indexrelid=to_regclass('tracker_analytics_v1.hand_contributions_hidden_policy_idx') AND indisvalid AND indisready),
 'nullProofValidatorDefinitionMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.safe_integer(jsonb)'::regprocedure),chr(13),''))='a3615d0068110c9bf33939ecf8f29024',
 'resultWithdrawalDefinitionMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.broadcast_withdrawal_v1()'::regprocedure),chr(13),''))='59860fa9484c0f48b70044f51c2380cf',
 'handWithdrawalBroadcastDefinitionMatches',md5(replace(pg_get_functiondef('public.flush_public_spectator_broadcast_v2(integer)'::regprocedure),chr(13),''))='e5439d6d813079754d9f2d55ef8a7d48',
 'enqueueWriteDefinitionMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.enqueue(text,uuid,boolean)'::regprocedure),chr(13),''))='0650893a716858e40a966b9c9dd2a460',
 'settlementEnqueueDefinitionMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.outcome_changed()'::regprocedure),chr(13),''))='ee4e45ea372523c4aef8371aa16cf430',
 'enqueueWritePrivate',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN (VALUES('anon'),('authenticated'),('service_role')) roles(name) WHERE n.nspname='tracker_analytics_v1' AND p.proname IN('enqueue','outcome_changed') AND has_function_privilege(roles.name,p.oid,'EXECUTE')),
 'identityLookupIndexMatches',EXISTS(SELECT 1 FROM pg_index i WHERE i.indexrelid=to_regclass('tracker_analytics_v1.hud_identity_latest') AND i.indisvalid AND i.indisready AND NOT i.indisunique AND pg_get_indexdef(i.indexrelid)='CREATE INDEX hud_identity_latest ON tracker_analytics_v1.hand_contributions USING btree (player_id, tournament_id, played_at DESC NULLS LAST, hand_id DESC)'),
 'identityMembershipDefinitionMatches',md5(replace(pg_get_functiondef('tracker_analytics_v1.public_context(uuid,uuid)'::regprocedure),chr(13),''))='1f0e816f649fd32728ed1f537cb2c090',
 'anonPrivateSchemaUsage',has_schema_privilege('anon','tracker_analytics_v1','USAGE'),
 'authenticatedPrivateSchemaUsage',has_schema_privilege('authenticated','tracker_analytics_v1','USAGE'),
 'anonCanReadSummary',has_function_privilege('anon','public.get_public_player_hud_summary_v1(uuid,uuid,text)','EXECUTE'),
 'anonCanReadHistory',has_function_privilege('anon','public.get_public_player_hud_history_v1(uuid,uuid,timestamptz,uuid)','EXECUTE'),
 'anonCanReadSummaryBatch',has_function_privilege('anon','public.get_public_player_hud_summary_batch_v1(uuid,uuid,text[])','EXECUTE'),
 'summaryBatchDefinitionMatches',md5(replace(pg_get_functiondef('public.get_public_player_hud_summary_batch_v1(uuid,uuid,text[])'::regprocedure),chr(13),''))='e090d874e79988a0c6795beb6aff390b',
 'orderedHistoryDefinitionMatches',md5(replace(pg_get_functiondef('public.get_public_player_hud_history_v1(uuid,uuid,timestamptz,uuid)'::regprocedure),chr(13),''))='4f8894bc8dd9114663ace03f9b3225e3',
 'anonCanClaimJobs',has_function_privilege('anon','public.claim_public_hud_jobs_v1(integer)','EXECUTE'),
 'authenticatedCanClaimJobs',has_function_privilege('authenticated','public.claim_public_hud_jobs_v1(integer)','EXECUTE'),
 'serviceCanClaimJobs',has_function_privilege('service_role','public.claim_public_hud_jobs_v1(integer)','EXECUTE'),
 'anonCanFlushBroadcast',has_function_privilege('anon','public.flush_public_spectator_broadcast_v2(integer)','EXECUTE'),
 'privateBrowserTableGrants',(SELECT count(*) FROM information_schema.role_table_grants WHERE table_schema='tracker_analytics_v1' AND grantee IN ('anon','authenticated','PUBLIC')),
 'observerTriggers',(SELECT jsonb_object_agg(tgname,tgenabled) FROM pg_trigger WHERE tgname IN ('hud_hand_changed','hud_outcome_changed','hud_result_changed','hud_visibility_changed','hud_withdrawal_broadcast')),
 'capturedRollbackDefinitions',(SELECT count(*) FROM spectator_projection_v2.compact_generation_originals_v1),
 'boundedCurrentHandIndexes',(SELECT count(*) FROM pg_indexes WHERE schemaname='public' AND indexname IN ('idx_public_hand_live_latest_v1','idx_public_hand_completed_latest_v1')),
 'capturedReadPlans',(SELECT count(*) FROM spectator_projection_v2.read_plan_originals_v1),
 'readPlanDefinitionsMatch',(SELECT count(*)=4 AND bool_and(CASE WHEN r.signature='public.get_public_tournament_clock_summary(uuid)' THEN EXISTS(SELECT 1 FROM spectator_projection_v2.clock_read_plan_original_v1 c WHERE c.signature=r.signature AND c.original_definition_hash=r.wrapped_definition_hash) WHEN r.signature='public.get_public_tournament_table_live_or_last_hand_v2(uuid,uuid)' THEN EXISTS(SELECT 1 FROM spectator_projection_v2.current_table_read_originals_v1 c WHERE c.signature=r.signature AND c.original_definition_hash=r.wrapped_definition_hash) ELSE md5(replace(pg_get_functiondef(r.signature::regprocedure),chr(13),''))=r.wrapped_definition_hash END) FROM spectator_projection_v2.read_plan_originals_v1 r),
 'currentTablePreparedDefinitionsMatch',(SELECT count(*)=2 AND bool_and(md5(replace(pg_get_functiondef(signature::regprocedure),chr(13),''))=prepared_definition_hash AND md5(definition)=original_definition_hash) FROM spectator_projection_v2.current_table_read_originals_v1),
 'currentTablePreparedSourceMatches',md5(replace(pg_get_functiondef('spectator_projection_v2.current_table_source_v1(uuid,uuid)'::regprocedure),chr(13),''))='0cc3f0c2998d2283e105db11c8b43c8d',
 'currentTablePreparedPrivateGrants',(SELECT count(*) FROM information_schema.role_table_grants WHERE table_schema='spectator_projection_v2' AND table_name IN ('current_table_publications_v1','current_table_read_originals_v1') AND grantee IN ('anon','authenticated','PUBLIC','service_role')),
 'currentTablePreparedRls',(SELECT count(*)=2 AND bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('spectator_projection_v2.current_table_publications_v1'::regclass,'spectator_projection_v2.current_table_read_originals_v1'::regclass)),
 'currentTablePreparedExpiryIndex',to_regclass('spectator_projection_v2.idx_public_current_table_expiry_v1') IS NOT NULL,
 'currentTablePreparedHelperPrivate',NOT (has_function_privilege('anon','spectator_projection_v2.current_table_source_v1(uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','spectator_projection_v2.current_table_source_v1(uuid,uuid)','EXECUTE') OR has_function_privilege('service_role','spectator_projection_v2.current_table_source_v1(uuid,uuid)','EXECUTE')),
 'clockReadPlanDefinitionMatches',(SELECT count(*)=1 AND bool_and(md5(c.definition)=c.original_definition_hash AND c.wrapped_definition_hash='6eb40dbf8d7444e09924a68ffd921d1b' AND EXISTS(SELECT 1 FROM spectator_projection_v2.clock_counts_original_v1 n WHERE n.signature=c.signature AND n.original_definition_hash=c.wrapped_definition_hash AND md5(n.definition)=n.original_definition_hash)) FROM spectator_projection_v2.clock_read_plan_original_v1 c),
 'clockCountsDefinitionMatches',(SELECT count(*)=1 AND bool_and(original_definition_hash='6eb40dbf8d7444e09924a68ffd921d1b' AND md5(definition)=original_definition_hash AND candidate_definition_hash='0996e504a583390a6ac36cad27937378' AND md5(replace(pg_get_functiondef(signature::regprocedure),chr(13),''))=candidate_definition_hash) FROM spectator_projection_v2.clock_counts_original_v1),
 'clockCountsDependencyMatches',md5(replace(pg_get_functiondef('floor_private.tournament_participation_v1(uuid)'::regprocedure),chr(13),''))='756297c6ef11962b0e53b4dcfc38a24d',
 'clockCountsReaderMetadataMatches',(SELECT count(*)=2 AND bool_and(proowner='postgres'::regrole AND proacl::text=CASE WHEN pronamespace='public'::regnamespace THEN '{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres}' ELSE '{postgres=X/postgres}' END) FROM pg_proc WHERE oid IN ('public.get_public_tournament_clock_summary(uuid)'::regprocedure,'floor_private.tournament_participation_v1(uuid)'::regprocedure)),
 'clockCountsPrivateRlsOwner',EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('spectator_projection_v2.clock_counts_original_v1') AND relrowsecurity AND relowner='postgres'::regrole),
 'clockCountsPrivateBrowserGrants',(SELECT count(*) FROM information_schema.role_table_grants WHERE table_schema='spectator_projection_v2' AND table_name='clock_counts_original_v1' AND grantee IN ('anon','authenticated','PUBLIC','service_role')),
 'clockReadPlanPrivateBrowserGrants',(SELECT count(*) FROM information_schema.role_table_grants WHERE table_schema='spectator_projection_v2' AND table_name='clock_read_plan_original_v1' AND grantee IN ('anon','authenticated','PUBLIC','service_role')),
 'readPlanPrivateBrowserGrants',(SELECT count(*) FROM information_schema.role_table_grants WHERE table_schema='spectator_projection_v2' AND table_name='read_plan_originals_v1' AND grantee IN ('anon','authenticated','PUBLIC','service_role')),
 'dispatcherUrlReady',coalesce(current_setting('app.supabase_url',true)='https://orlesggcjamwuknxwcpk.supabase.co',false),
 'workerVaultCredentialPresent',EXISTS(SELECT 1 FROM vault.decrypted_secrets WHERE name='PUBLIC_HUD_WORKER_SECRET' AND length(decrypted_secret)>0),
 'configuration',(SELECT to_jsonb(c) FROM tracker_analytics_v1.config c WHERE singleton),
 'dispatchSchedules',(SELECT jsonb_agg(jsonb_build_object('name',jobname,'schedule',schedule,'active',active)) FROM cron.job WHERE jobname IN ('public-hud-projection-v1-dispatch','public-spectator-v2-dispatch'))
);
